def lpHaarSignedBlock (𝕜 : Type*) [RCLike 𝕜] (p : BanachExponent)
    (n : ℕ) (S : Finset (Fin (2 ^ n))) (θ : Fin (2 ^ n) → Bool) : IntervalLp 𝕜 p :=
  ∑ k ∈ S, signedValue (θ k) (lpHaarDyadic 𝕜 p n k)

